input.content:
// Processes raw community logos in a headless page canvas:
// 1. adhoc-studio-src.jpg  → adhoc-studio.png   (white → transparent, mark stays black)
// 2. logicroom.webp        → logicroom-mark.png (crop the molecule mark, keep alpha)
const { chromium } = require('playwright');
const { writeFileSync } = require('node:fs');

const DIR = '~/dev/ivue/docs_v2/public/community';

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('about:blank');

  const results = await page.evaluate(async ({ adhocUrl, logicUrl }) => {
    const load = (src) =>
      new Promise((resolveImage, rejectImage) => {
        const image = new Image();
        image.onload = () => resolveImage(image);
        image.onerror = rejectImage;
        image.src = src;
      });

    // ---- adhoc: luminance → alpha, mark forced black ----
    const adhoc = await load(adhocUrl);
    const scale = 4; // upscale the tiny 142px source for crisp tiles
    const adhocCanvas = document.createElement('canvas');
    adhocCanvas.width = adhoc.width * scale;
    adhocCanvas.height = adhoc.height * scale;
    const adhocContext = adhocCanvas.getContext('2d');
    adhocContext.imageSmoothingQuality = 'high';
    adhocContext.drawImage(adhoc, 0, 0, adhocCanvas.width, adhocCanvas.height);
    const adhocPixels = adhocContext.getImageData(0, 0, adhocCanvas.width, adhocCanvas.height);
    const data = adhocPixels.data;
    for (let index = 0; index < data.length; index += 4) {
      const luminance = (data[index] + data[index + 1] + data[index + 2]) / 3;
      data[index] = 10; data[index + 1] = 12; data[index + 2] = 16;
      data[index + 3] = 255 - luminance;
    }
    adhocContext.putImageData(adhocPixels, 0, 0);
    const adhocOut = adhocCanvas.toDataURL('image/png');

    // ---- logicroom: crop the mark (left square-ish region with ink) ----
    const logic = await load(logicUrl);
    const probeCanvas = document.createElement('canvas');
    probeCanvas.width = logic.width;
    probeCanvas.height = logic.height;
    const probeContext = probeCanvas.getContext('2d');
    probeContext.drawImage(logic, 0, 0);
    const probe = probeContext.getImageData(0, 0, logic.width, logic.height).data;
    // find the mark's bounds: colored (saturated) pixels only, so the
    // white wordmark is ignored
    let minX = logic.width, maxX = 0, minY = logic.height, maxY = 0;
    for (let y = 0; y < logic.height; y++) {
      for (let x = 0; x < logic.width; x++) {
        const at = (y * logic.width + x) * 4;
        const red = probe[at], green = probe[at + 1], blue = probe[at + 2], alpha = probe[at + 3];
        const saturation = Math.max(red, green, blue) - Math.min(red, green, blue);
        if (alpha > 40 && saturation > 40) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }
    const cropWidth = maxX - minX + 1;
    const cropHeight = maxY - minY + 1;
    const markCanvas = document.createElement('canvas');
    markCanvas.width = cropWidth * 3;
    markCanvas.height = cropHeight * 3;
    const markContext = markCanvas.getContext('2d');
    markContext.imageSmoothingQuality = 'high';
    markContext.drawImage(logic, minX, minY, cropWidth, cropHeight, 0, 0, markCanvas.width, markCanvas.height);
    const logicOut = markCanvas.toDataURL('image/png');

    return { adhocOut, logicOut, bounds: { minX, maxX, minY, maxY } };
  }, {
    adhocUrl: 'data:image/jpeg;base64,' + require_placeholder_adhoc,
    logicUrl: 'data:image/webp;base64,' + require_placeholder_logic,
  });

  writeFileSync(`${DIR}/adhoc-studio.png`, Buffer.from(results.adhocOut.split(',')[1], 'base64'));
  writeFileSync(`${DIR}/logicroom-mark.png`, Buffer.from(results.logicOut.split(',')[1], 'base64'));
  console.log('bounds:', JSON.stringify(results.bounds));
  await browser.close();
})();

